      if (current.length > 0) {
        tokens.push(current);
        current = '';
      }
      // any other character (including apostrophe, space, punctuation, accented letters) is a separator
    }
  }
  if (current.length > 0) {
    tokens.push(current);
  }
  return tokens;
}

